	private static void assertProbeBoundedRowKernel(boolean compiled) throws Exception {
		String property = "rdf4j.lmdb.adaptiveProbe.bufferRows";
		String previous = System.getProperty(property);
		System.setProperty(property, "4");
		try {
			// ORDER makes the generated shape deliberately non-resumable, so both tiers own a private materialization
			// buffer. Resumable generated kernels stream directly into the caller's bounded buffer and need no inner
			// cap.
			Kernel ir = new Kernel(1, List.of(new EnumerateDomain(0, 0)),
					new Emit(new int[] { 0 }, false, new OutputMods(new int[] { 0 }, null, false, -1L, 0L)));
			long[] domain = { 1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L };
			JaninoKernel control = rowKernel(ir, false);
			try {
				control.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0], new long[0], new long[0],
						new long[][] { domain }));
				assertThat(control.fill(new long[64], 64)).as("control row cardinality").isEqualTo(8);
			} finally {
				control.close();
			}
			JaninoKernel kernel = rowKernel(ir, compiled);
			try (LmdbNativeProbeDeadline.Scope ignored = LmdbNativeProbeDeadline
					.enter(System.nanoTime() + TimeUnit.HOURS.toNanos(1L))) {
				org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelCancellation cancellation = LmdbNativeProbeDeadline
						.currentKernelCancellation();
				assertThat(cancellation.materializationRowLimit()).isEqualTo(4);
				kernel.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0], new long[0],
						new long[0], new long[][] { domain })
								.withCancellation(cancellation));
				assertThatThrownBy(() -> kernel.fill(new long[64], 64))
						.as(compiled ? "compiled probe materialization" : "interpreted probe materialization")
						.isInstanceOf(
								org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelCancelledException.class);
			} finally {
				kernel.close();
			}
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

