	private void assertParityInterpreterServed(String query) {
		List<String> compiled = canonical(rows(query, true));
		LmdbNativeKernelExecution.resetMetrics();
		KernelExecutionTestAccess.resetCostCalibration();
		List<String> interpreted = canonical(rows(query, false));
		assertThat(interpreted).isEqualTo(compiled);
		assertThat(LmdbNativeKernelExecution.OPENED.get())
				.as("the interpreted arm must serve this query through the row kernel interpreter")
				.isPositive();
	}

	/** Ordered queries compare row lists positionally (the ORDER BY window must be identical, not just the bag). */
	private void assertOrderedParity(String query) {
		List<String> compiled = ordered(rows(query, true));
		LmdbNativeKernelExecution.resetMetrics();
		KernelExecutionTestAccess.resetCostCalibration();
		List<String> interpreted = ordered(rows(query, false));
		assertThat(interpreted).isEqualTo(compiled);
		assertThat(LmdbNativeKernelExecution.OPENED.get())
				.as("the interpreted arm must serve this query through the row kernel interpreter")
				.isPositive();
	}

	private void assertParityStaysSemanticNative(String query) {
		List<String> compiled = canonical(rows(query, true));
		LmdbNativeKernelExecution.resetMetrics();
		KernelExecutionTestAccess.resetCostCalibration();
		long compiledBefore = KernelExecutionTestAccess.semanticNativeCompiles();
		long hostedBefore = KernelExecutionTestAccess.hostedGenericCompiles();
		long islandsBefore = KernelExecutionTestAccess.islandCompiles();
		List<String> interpreted = canonical(rows(query, false));
		assertThat(interpreted).isEqualTo(compiled);
		assertThat(KernelExecutionTestAccess.semanticNativeCompiles() - compiledBefore).isPositive();
		assertThat(KernelExecutionTestAccess.hostedGenericCompiles()).isEqualTo(hostedBefore);
		assertThat(KernelExecutionTestAccess.islandCompiles()).isEqualTo(islandsBefore);
	}

	private List<BindingSet> rows(String query, boolean janino) {
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", Boolean.toString(janino));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		}
	}

	private static List<Long> runSliceKernel(Kernel ir, boolean compiled, long[] domain) throws Exception {
		JaninoKernel kernel = rowKernel(ir, compiled);

		try {
			kernel.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0], new long[0], new long[0],
					new long[][] { domain }));
			long[] buffer = new long[64];
			List<Long> rows = new ArrayList<>();
			int filled;
			while ((filled = kernel.fill(buffer, 64)) > 0) {
				for (int i = 0; i < filled; i++) {
					rows.add(buffer[i]);
				}
			}
			return rows;
		} finally {
			kernel.close();
		}
	}

	private static JaninoKernel rowKernel(Kernel ir, boolean compiled) throws Exception {
		JaninoKernel kernel;
		if (compiled) {
			kernel = LmdbNativeJaninoCodegen.kernel(ir.shapeKey(), ir.className(),
					() -> LmdbNativeKernelEmitter.emit(ir), Long.MAX_VALUE);
			if (kernel == null) {
				kernel = LmdbNativeJaninoCodegen.awaitKernel(ir.shapeKey(), 30, TimeUnit.SECONDS);
			}
		} else {
			kernel = LmdbNativeKernelInterpreter.forRows(ir);
		}
		assertThat(kernel).as(compiled ? "compiled kernel" : "interpreted kernel").isNotNull();
		return kernel;
	}

	private static List<String> canonical(List<BindingSet> rows) {
		List<String> result = ordered(rows);
		result.sort(String::compareTo);
		return result;
	}

	private static List<String> ordered(List<BindingSet> rows) {
		List<String> result = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			List<String> bindings = new ArrayList<>(row.size());
			for (Binding binding : row) {
				bindings.add(binding.getName() + "=" + binding.getValue());
			}
			bindings.sort(String::compareTo);
			result.add(String.join("|", bindings));
		}
		return result;
	}

	private static String prefixes() {
		return "PREFIX ex: <" + EX + ">\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";
	}
